<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { RouterLink } from 'vue-router'
import { useAppStore } from '@/stores/app'
import { fetchHome, type PublicHome } from '@/api/site'

const appStore = useAppStore(); const { name, englishName, tagline } = storeToRefs(appStore)
const home = ref<PublicHome | null>(null); const loading = ref(true); const error = ref(false)
const modules = [{to:'/tutorials',index:'01',label:'教程',desc:'从知识体系进入系统课程'},{to:'/blog',index:'02',label:'博客',desc:'记录判断、方法与复盘'},{to:'/portfolio',index:'03',label:'作品',desc:'用真实项目验证学习'},{to:'/english',index:'04',label:'英语',desc:'长期积累语言能力'}]
const systems = [{to:'/tutorials?categorySlug=java-fullstack',index:'01',title:'Java 全栈知识体系',desc:'从语言基础到后端工程、数据库与前端协作，构建可落地的开发能力。'},{to:'/tutorials?categorySlug=computer-science',index:'02',title:'计算机基础知识体系',desc:'围绕算法、操作系统、网络与组成原理，建立稳定的技术底座。'},{to:'/tutorials?categorySlug=agent-development',index:'03',title:'智能体开发知识体系',desc:'理解大模型、工具调用与 Agent 架构，持续跟进智能应用开发。'}]
const typeLabels:Record<string,string>={TUTORIAL:'教程章节',BLOG:'博客记录',PORTFOLIO:'项目作品'}
function linkOf(item:{type:string;tutorialSlug:string|null;chapterSlug:string|null;slug:string|null}){if(item.type==='TUTORIAL')return `/tutorials/${item.tutorialSlug??''}/${item.chapterSlug??''}`;if(item.type==='BLOG')return `/blog/${item.slug??''}`;return `/portfolio/${item.slug??''}`}
function dateOf(value:string){const date=new Date(value);return Number.isNaN(date.getTime())?value:new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',year:'numeric'}).format(date)}
onMounted(async()=>{try{home.value=await fetchHome()}catch{error.value=true}finally{loading.value=false}})
</script>

