  <main class="home-content"><section class="home-section home-section--updates"><header><div><p class="home-kicker">LATEST NOTES</p><h2>最近更新</h2></div><RouterLink to="/search">浏览全部 →</RouterLink></header><div v-if="loading" class="home-state">正在整理最新内容…</div><div v-else-if="error" class="home-state">暂时无法读取更新，内容本身仍可从顶部导航访问。</div><div v-else-if="!home?.latestUpdates.length" class="home-state">第一条更新正在路上。</div><ol v-else class="update-list"><li v-for="(item,index) in home.latestUpdates" :key="`${item.type}-${item.id}`"><RouterLink :to="linkOf(item)"><span class="update-list__number">{{String(index+1).padStart(2,'0')}}</span><div><small>{{typeLabels[item.type]??item.type}}</small><h3>{{item.title}}</h3></div><time :datetime="item.activityAt">{{dateOf(item.activityAt)}}</time><i>→</i></RouterLink></li></ol></section>
    <section class="home-section home-section--systems"><header><div><p class="home-kicker">LEARNING MAP</p><h2>精选知识体系</h2></div><RouterLink to="/tutorials">进入教程中心 →</RouterLink></header><div class="system-grid"><RouterLink v-for="system in systems" :key="system.to" :to="system.to"><span>{{system.index}}</span><h3>{{system.title}}</h3><p>{{system.desc}}</p><i>探索体系 →</i></RouterLink></div></section>
    <section class="home-section home-section--projects"><header><div><p class="home-kicker">SELECTED WORK</p><h2>把学习做成作品</h2></div><RouterLink to="/portfolio">全部作品 →</RouterLink></header><div v-if="home?.featuredProjects.length" class="project-grid"><RouterLink v-for="(project,index) in home.featuredProjects" :key="project.id" :to="`/portfolio/${project.slug}`" class="project-card" :class="{'is-featured':index===0}"><div v-if="project.coverUrl" class="project-card__cover" :style="{backgroundImage:`url(${project.coverUrl})`}"/><div v-else class="project-card__cover"><span>STAR<br>RAIN</span></div><div class="project-card__body"><small>{{project.projectStatus}} · PROJECT {{String(index+1).padStart(2,'0')}}</small><h3>{{project.title}}</h3><p>{{project.summary}}</p><b>阅读项目复盘 →</b></div></RouterLink></div><div v-else class="home-state">作品资料正在整理，可先从教程与博客了解项目脉络。</div></section>
    <section v-if="home?.aboutPreview" class="home-author"><p class="home-kicker">ABOUT THE AUTHOR</p><div><h2>{{home.aboutPreview.displayName||'站点作者'}}</h2><p>{{home.aboutPreview.headline||home.aboutPreview.bio}}</p><RouterLink to="/about">认识作者与这套知识系统 →</RouterLink></div></section>
  </main>
</div></template>

